'use strict';process.env.LTS_FLOW_RELEASE='v463';
const {chromium,webkit}=require('playwright'),fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const {setup}=require('./lts_v382_browser.cjs'),fixture=require('./lts_v463_fixture.cjs'),baseFixture=require('./lts_v379_fixtures.cjs');
const base=process.env.LTS_BROWSER_BASE||'http://127.0.0.1:8788',out='qa/v463',now='2026-11-17T17:00:00Z';fs.mkdirSync(out,{recursive:true});
const hash=j=>crypto.createHash('sha256').update(JSON.stringify(j)).digest('hex');
async function go(frame,name){await frame.locator('#nav [data-v="'+name+'"]:visible,#dx1MobileNav [data-mobile-route="'+name+'"]:visible').click();await frame.waitForFunction(x=>V===x,name);}
async function context(browser,width){const h=await setup(browser,width,980,now);let fail=false,defer=false,deferObserved=false;const details=[];const send=(r,j)=>r.fulfill({status:200,contentType:'application/json',body:JSON.stringify(j)});
 const refresh=()=>({state:defer?'running':'ready',required:defer,cached_available:true,request_version:deferObserved?3:2,completed_version:defer?2:deferObserved?3:2});
 await h.ctx.route('**/rest/v1/rpc/lts_browser_product_v1',r=>send(r,{ok:true,mvp:baseFixture.product(),refresh:refresh()}));
 await h.ctx.route('**/rest/v1/rpc/lts_browser_product_refresh_status_v415',r=>send(r,{ok:true,refresh:refresh()}));
 await h.ctx.route('**/rest/v1/rpc/lts_browser_expenses_v229',r=>send(r,fixture.report(r.request().postDataJSON())));
 await h.ctx.route('**/rest/v1/rpc/lts_browser_wealth_detail_v242',r=>send(r,fixture.wealth()));
 await h.ctx.route('**/rest/v1/rpc/lts_browser_cash_today_v242',r=>send(r,require('./lts_v458_cash_fixture.cjs')(now)));
 await h.ctx.route('**/rest/v1/rpc/lts_browser_budget_read_v441',r=>send(r,require('./lts_v441_fixture.cjs')()));
 await h.ctx.route('**/rest/v1/rpc/lts_browser_expense_scope_detail_v374',r=>{const args=r.request().postDataJSON();details.push(args);if(fail||defer)return r.fulfill({status:503,contentType:'application/json',body:JSON.stringify({code:defer?'55000':'57014',message:'Internal RPC SQL implementation deliberately unavailable'})});return send(r,fixture.detail(args));});
 return Object.assign(h,{details,setFail:x=>fail=x,setDefer:x=>{defer=x;deferObserved=true;}});}
async function open(h,release){await h.page.goto(base+'/releases/'+release+'/app.html',{waitUntil:'domcontentloaded'});await h.page.waitForFunction(()=>document.getElementById('shell')?.contentDocument?.body?.dataset.ltsBootState==='ready');const frame=h.page.frames().find(f=>f.url().includes('/releases/'+release+'/index.html'));assert(frame);await frame.waitForFunction(()=>window.__LTS_V178_STATE&&['wealth','forecast','awards','dashboardReport'].every(k=>__LTS_V178_STATE[k].status==='ready'));await h.page.waitForLoadState('networkidle');return frame;}
async function run(browser,engine,width){const prior=await context(browser,width),h=await context(browser,width),label=engine+'-'+width;let frame;
 try{
  const before=await open(prior,'v458');await go(before,'Fluxo Diário');await before.waitForFunction(()=>!FLOWLOADING&&FLOWQ&&window.__LTS_V441_FLOW);const original=await before.evaluate(()=>FLOWQ),oldHeight=await before.locator('#v441FlowSummary').evaluate(e=>e.getBoundingClientRect().height);
  frame=await open(h,'v463');await frame.waitForFunction(()=>window.__LTS_V463_DEBT?.installed);await go(frame,'Fluxo Diário');await frame.waitForFunction(()=>!FLOWLOADING&&FLOWQ&&window.__LTS_V441_FLOW);
  assert.equal(hash(await frame.evaluate(()=>FLOWQ)),hash(original),'Same canonical financial flow as the immutable predecessor');assert.equal(await frame.locator('#v441FlowSummary,.v365-bridge,.v423-bank-evidence').count(),0);assert(oldHeight>100);
  const financial=await frame.evaluate(()=>JSON.stringify(D));await h.page.screenshot({path:out+'/'+label+'-flow-default.png',fullPage:true});
  await frame.getByLabel('Opções do Fluxo').click();assert(await frame.locator('#v441FlowPremises').isVisible());await h.page.screenshot({path:out+'/'+label+'-flow-options.png',fullPage:true});await frame.getByLabel('Opções do Fluxo').press('Escape');
  await go(frame,'Despesas');const panel=frame.locator('.v353-presentation');await panel.waitFor({state:'visible'});assert.equal(await panel.getByLabel('Forma de pagamento').inputValue(),'');
  const total=()=>panel.locator('.v353-metric').filter({hasText:/^Total/}).innerText();assert.match(await total(),/185,00/);
  await panel.getByLabel('Forma de pagamento').selectOption('card');assert.match(await total(),/140,00/);await h.page.screenshot({path:out+'/'+label+'-cards-by-category.png',fullPage:true});
  const drawer=frame.locator('#v178Drawer'),ready=()=>frame.waitForFunction(()=>window.__LTS_V178_STATE.detail&&!window.__LTS_V178_STATE.detail.loading);
  await panel.getByRole('button',{name:'Saúde',exact:true}).click();await ready();assert.match(await drawer.innerText(),/90,00/);assert.equal(await drawer.locator('tbody tr').count(),2);assert(!/Nenhum lançamento/.test(await drawer.innerText()));await h.page.screenshot({path:out+'/'+label+'-health-card-detail.png',fullPage:true});await drawer.getByRole('button',{name:'Fechar',exact:true}).click();
  await panel.getByLabel('Forma de pagamento').selectOption('account');assert.match(await total(),/45,00/);await panel.getByRole('button',{name:'Saúde',exact:true}).click();await ready();assert.equal(await drawer.locator('tbody tr').count(),1);assert.match(await drawer.innerText(),/20,00/);await drawer.getByRole('button',{name:'Fechar',exact:true}).click();
  await panel.getByLabel('Forma de pagamento').selectOption('');assert.match(await total(),/185,00/);const food=panel.locator('details.v353-node').filter({has:frame.locator('summary>span',{hasText:'Alimentação'})});await food.locator(':scope>summary').click();await food.getByRole('button',{name:'iFood',exact:true}).click();await ready();assert.equal(await drawer.locator('tbody tr').count(),1);assert.match(await drawer.innerText(),/25,00/);await drawer.getByRole('button',{name:'Fechar',exact:true}).click();
  h.setFail(true);await frame.evaluate(()=>__LTS_V227_TRANSPORT.invalidate(false));await panel.getByRole('button',{name:'Saúde',exact:true}).click();await ready();const errorText=await drawer.innerText();assert(/Não foi possível carregar os lançamentos/.test(errorText));assert(!/Nenhum lançamento|Internal RPC|SQL implementation/.test(errorText));assert(await drawer.locator('.v178-retry').isVisible());await h.page.screenshot({path:out+'/'+label+'-detail-failure.png',fullPage:true});
  h.setFail(false);await drawer.locator('.v178-retry').click();await ready();assert.equal(await drawer.locator('tbody tr').count(),3);assert.match(await drawer.innerText(),/110,00/);await drawer.getByRole('button',{name:'Fechar',exact:true}).click();
  h.setDefer(true);await frame.evaluate(async()=>{__LTS_V227_TRANSPORT.invalidate(false);await __LTS_V415_REFRESH.poll();});await panel.getByRole('button',{name:'Saúde',exact:true}).click();await ready();h.setDefer(false);await frame.evaluate(()=>__LTS_V415_REFRESH.poll());await ready();assert.equal(await drawer.locator('tbody tr').count(),3);const count=h.details.length;await frame.evaluate(()=>window.dispatchEvent(new Event('lts:product-refresh-ready')));assert.equal(h.details.length,count);await drawer.getByRole('button',{name:'Fechar',exact:true}).click();
  await go(frame,'Patrimônio');await frame.waitForFunction(()=>document.querySelector('[data-v386-debt="volvo"] .v463-debt-basis'));assert.match(await frame.locator('[data-v386-debt="volvo"]').innerText(),/Estimado após a parcela/);assert.match(await frame.locator('.v365-wealth-totals').innerText(),/Patrimônio líquido estimado/);assert.equal(await frame.locator('.v463-debt-basis[open]').count(),0);await h.page.screenshot({path:out+'/'+label+'-wealth-estimate.png',fullPage:true});await frame.locator('[data-v386-debt="volvo"] summary').click();await h.page.screenshot({path:out+'/'+label+'-wealth-origin.png',fullPage:true});
  assert.equal(await frame.evaluate(()=>JSON.stringify(D)),financial,'Presentation does not write source financial data');assert(await frame.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2));assert.deepEqual(h.errors,[]);assert.deepEqual(h.writes,[]);
  return{pass:true,engine,width,synthetic:true,private_session:false,physical_device:false,flow_financial_parity:true,removed_extra_summary_height:oldHeight,card_account_total_and_category_details:true,no_false_empty_after_failed_read:true,one_recovery_after_verified_ready:true,dated_debt_estimate_and_disclosed_basis:true,financial_writes:0};
 }catch(e){await h.page.screenshot({path:out+'/'+label+'-failure.png',fullPage:true}).catch(()=>{});console.error(JSON.stringify({label,error:e.stack,errors:h.errors,writes:h.writes,details:h.details,body:frame?await frame.locator('body').innerText().catch(()=>null):null}));throw e;}finally{await prior.ctx.close();await h.ctx.close();}}
(async()=>{const results=[];const engines=process.env.LTS_TEST_ENGINE==='chromium'?[['chromium',chromium]]:[['chromium',chromium],['webkit',webkit]];for(const[name,type]of engines){const browser=await type.launch({headless:true,...(name==='chromium'&&process.env.LTS_CHROMIUM_EXECUTABLE_PATH?{executablePath:process.env.LTS_CHROMIUM_EXECUTABLE_PATH}:{})});try{for(const width of [393,1366])results.push(await run(browser,name,width));}finally{await browser.close();}}fs.writeFileSync(out+'/customer-feedback-results.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results));})().catch(e=>{console.error(e);process.exitCode=1});
